{"path": "tests/test_users.py", "file_text": "from app.api.handlers import handle_get_user, handle_create_user


def test_get_user_ok():
    assert handle_get_user({"id": "1"}) == (200, {"id": 1, "name": "Ada", "email": "ada@example.com"})


def test_get_user_invalid():
    assert handle_get_user({"id": "abc"})[0] == 400


def test_get_user_missing():
    assert handle_get_user({"id": "99"})[0] == 404


def test_create_user_ok():
    status, user = handle_create_user({"name": "Bob", "email": "bob@example.com"})
    assert status == 201
    assert user["name"] == "Bob"
    assert user["email"] == "bob@example.com"
    assert "id" in user


def test_create_user_trim_name():
    status, user = handle_create_user({"name": "  Bob  ", "email": "bob2@example.com"})
    assert status == 201
    assert user["name"] == "Bob"


def test_create_user_invalid_name():
    assert handle_create_user({"name": "", "email": "test@test.com"})[0] == 400
    assert handle_create_user({"name": "a" * 51, "email": "test@test.com"})[0] == 400


def test_create_user_invalid_email():
    assert handle_create_user({"name": "Bob", "email": "invalid-email"})[0] == 400


def test_create_user_email_exists():
    handle_create_user({"name": "Bob", "email": "exists@example.com"})
    assert handle_create_user({"name": "Bob2", "email": "EXISTS@example.com"}) == (
        409,
        {"error": "email already exists"},
    )
"}

